from pqattest import MerkleSigner, auth_state_unwrap, auth_state_wrap

def tok():
    n = 0
    def t(size):
        nonlocal n
        n += 1
        return n.to_bytes(8, "big").rjust(size, b"\x00")
    return t

s = MerkleSigner(height=2, token_bytes=tok())
# equal target at 0 still returns envelope of unchanged state
(before, after), env = s.advance_to_with_auth_state(0, key=b"k", generation=2**64-1)
assert (before, after) == (0, 0)
assert env == auth_state_wrap(s.checkpoint(), scheme="merkle", key=b"k", generation=2**64-1)
sch, gen, cp = auth_state_unwrap(env, key=b"k")
assert (sch, gen) == ("merkle", 2**64-1) and int.from_bytes(cp[11:13], "big") == 0

# byte-for-byte: envelope from method == advance + explicit checkpoint + wrap
s2 = MerkleSigner(height=2, token_bytes=tok())
s2.advance_to(3)
_, env1 = s.advance_to_with_auth_state(3, key=b"k2", generation=5)
assert env1 == auth_state_wrap(s2.checkpoint(), scheme="merkle", key=b"k2", generation=5)

# failure validation matrix
for bad in (True, False, 1.5, None):
    try:
        s.advance_to_with_auth_state(bad, key=b"k", generation=0)
        raise AssertionError
    except TypeError:
        pass
for bad in (-1, 5):
